// Staged here until the Android project exists: `src-tauri/gen/android` is generated by `tauri android init`, and this
// file is copied into it (docs/engineering/data-layer.md, "The Android checklist"). The `package` line and
// `TEXT_READER_CLASS` in `src/domains/finance/recognize_android.rs` both follow the Android namespace.
package com.palekodama.eden

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Color
import android.graphics.Matrix
import android.graphics.pdf.PdfRenderer
import android.media.ExifInterface
import android.os.Build
import android.os.ParcelFileDescriptor
import android.system.Os
import android.system.OsConstants
import com.google.android.gms.tasks.Tasks
import com.google.mlkit.vision.common.InputImage
import com.google.mlkit.vision.text.TextRecognition
import com.google.mlkit.vision.text.latin.TextRecognizerOptions
import java.io.ByteArrayInputStream
import org.json.JSONArray
import org.json.JSONObject

/**
 * The document reader's recogniser on Android (D-190).
 *
 * Called from Rust over JNI on a blocking thread. ML Kit's bundled Latin model
 * (`com.google.mlkit:text-recognition`) runs on the device; the Play-services variant, which downloads its model, is
 * never used. Each call answers `{ "lines": [{ "text", "confidence", "page" }], "pages", "pagesRead" }`, or null when
 * the file cannot be decoded. Nothing is written to disk and nothing is logged: a PDF is handed to `PdfRenderer`
 * through an anonymous memory file (`memfd_create`, Android 11 and later); before that a scanned PDF reads as null.
 */
object EdenTextReader {
    /** A rendered page's long edge, in pixels. */
    private const val MAX_EDGE = 3000
    /** A page is rendered at about twice its size in points. */
    private const val SCALE = 2f

    @JvmStatic
    fun readImage(context: Context, bytes: ByteArray): String? {
        val bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.size) ?: return null
        val upright = rotated(bitmap, orientation(bytes))
        return try {
            answer(recognize(upright, 0), 1, 1)
        } finally {
            if (upright !== bitmap) upright.recycle()
            bitmap.recycle()
        }
    }

    @JvmStatic
    fun readPdf(context: Context, bytes: ByteArray, maxPages: Int): String? {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.R) return null
        val memory = Os.memfd_create("eden-document", 0)
        try {
            var written = 0
            while (written < bytes.size) written += Os.write(memory, bytes, written, bytes.size - written)
            Os.lseek(memory, 0, OsConstants.SEEK_SET)
            val descriptor = ParcelFileDescriptor.dup(memory)
            PdfRenderer(descriptor).use { renderer ->
                val total = renderer.pageCount
                val count = minOf(total, maxPages)
                val lines = JSONArray()
                for (index in 0 until count) {
                    renderer.openPage(index).use { page ->
                        var factor = SCALE
                        val longEdge = maxOf(page.width, page.height) * factor
                        if (longEdge > MAX_EDGE) factor *= MAX_EDGE / longEdge
                        val width = (page.width * factor).toInt().coerceAtLeast(1)
                        val height = (page.height * factor).toInt().coerceAtLeast(1)
                        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
                        bitmap.eraseColor(Color.WHITE)
                        page.render(bitmap, null, null, PdfRenderer.Page.RENDER_MODE_FOR_PRINT)
                        try {
                            val found = recognize(bitmap, index)
                            for (i in 0 until found.length()) lines.put(found.get(i))
                        } finally {
                            bitmap.recycle()
                        }
                    }
                }
                return answer(lines, total, count)
            }
        } catch (error: Exception) {
            return null
        } finally {
            Os.close(memory)
        }
    }

    private fun recognize(bitmap: Bitmap, page: Int): JSONArray {
        val recognizer = TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS)
        try {
            val text = Tasks.await(recognizer.process(InputImage.fromBitmap(bitmap, 0)))
            val lines = JSONArray()
            for (block in text.textBlocks) {
                for (line in block.lines) {
                    lines.put(
                        JSONObject()
                            .put("text", line.text)
                            .put("confidence", line.confidence.toDouble())
                            .put("page", page)
                    )
                }
            }
            return lines
        } finally {
            recognizer.close()
        }
    }

    private fun answer(lines: JSONArray, pages: Int, pagesRead: Int): String =
        JSONObject().put("lines", lines).put("pages", pages).put("pagesRead", pagesRead).toString()

    private fun orientation(bytes: ByteArray): Int =
        try {
            ExifInterface(ByteArrayInputStream(bytes))
                .getAttributeInt(ExifInterface.TAG_ORIENTATION, ExifInterface.ORIENTATION_NORMAL)
        } catch (error: Exception) {
            ExifInterface.ORIENTATION_NORMAL
        }

    /** The photo turned the way its EXIF orientation says, so a picture taken sideways is read upright. */
    private fun rotated(bitmap: Bitmap, orientation: Int): Bitmap {
        val matrix = Matrix()
        when (orientation) {
            ExifInterface.ORIENTATION_ROTATE_90 -> matrix.postRotate(90f)
            ExifInterface.ORIENTATION_ROTATE_180 -> matrix.postRotate(180f)
            ExifInterface.ORIENTATION_ROTATE_270 -> matrix.postRotate(270f)
            ExifInterface.ORIENTATION_FLIP_HORIZONTAL -> matrix.preScale(-1f, 1f)
            ExifInterface.ORIENTATION_FLIP_VERTICAL -> matrix.preScale(1f, -1f)
            ExifInterface.ORIENTATION_TRANSPOSE -> { matrix.postRotate(90f); matrix.preScale(-1f, 1f) }
            ExifInterface.ORIENTATION_TRANSVERSE -> { matrix.postRotate(270f); matrix.preScale(-1f, 1f) }
            else -> return bitmap
        }
        return Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)
    }
}
